head.script:
/* 프로그램ID */
scwin.pgmId = 'PGJ173F01';

/* 최상단의 선언 */
scwin.isMain = function() {
	return true;
}

/* 페이지 건수 */
var pageCnt = 0;

/* 탭위치 동산 부동산 구분코드 */
scwin.rletMvprpDvsCd = 'R'

scwin.onpageload = function() {

	/* 메뉴 */
	if(!scutilo.isEmpty(scwin.pgmId)){
	   $p.main().wfm_side.scope.scwin.menuFocus(scwin.pgmId.slice(0,6));
	}

	let flag = com.getParameter("tap");
	if (!scutilo.isEmpty(flag) && flag == "M") {
		tac_auctnFrml.setSelectedTabIndex(1);
		dma_auctnFrmlSrch.set("cortAuctnNtcEtcDtlDvsCd","0005502");
		dma_auctnFrmlSrch.set("tapFlag",1);
		dma_auctnFrmlSrch.set("titlSrchwd","");
	}
	ibx_frmlNm1.focus();
	if (pgjUtil.getCookie("pageCnt")==null) {
		pageCnt =20;
		sbx_pageCnt1.setValue('20');
	} else {
		pageCnt = Number(pgjUtil.getCookie("pageCnt"));
		sbx_pageCnt1.setValue(pgjUtil.getCookie("pageCnt"));
	}
	scwin.auctnFrmlListMain(true,pageCnt);
};

scwin.onpageunload = function() {

};

//웹접근성으로 인한 title제공 수정
scwin.titleFormatter = function(e) {
    return "";
}

/**
 * 페이징 처리 Main
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.08.05.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.auctnFrmlListMain = function(isFirst,pageCnt){

	/* 최초 조회 여부 */
	if (isFirst) {
        dma_pageInfo.set("pageNo" , 1);
        dma_pageInfo.set("totalYn", "Y");
	} else {
        dma_pageInfo.set("totalYn", "N");
    }
	dma_pageInfo.set("pageSize", pageCnt);
	com.executeSubmission(sbm_selectAuctnFrmlLst);
}

/**
 * 페이징 처리
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.08.05.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.sbm_selectAuctnFrmlLst_submitdone = function(e) {
	var tapFlag = dma_auctnFrmlSrch.get("tapFlag");

	if (tapFlag==0 || tapFlag==null || tapFlag=="") {
		/* 페이지 dma, 해당 페이지 리스트 ID, 해당 gridView ID */
		scutilo.setPagingInfo(dma_pageInfo, pgl_auctnFrmlList, grd_auctnFrmlList1);
	} else {
		scutilo.setPagingInfo(dma_pageInfo, pgl_auctnFrmlList2, grd_auctnFrmlList2);
	}

};

/**
 * 부동산 탭 페이지 이동시 해당 페이지 번호
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.08.05.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.pgl_auctnFrmlList_onviewchange = function(info) {
	dma_pageInfo.set("pageNo" , info.newSelectedIndex );
    dma_pageInfo.set("bfPageNo",info.oldSelectedIndex );
	scwin.auctnFrmlListMain(false,pageCnt);//조회처리
};

/**
 * 동산 탭 페이지 이동시 해당 페이지 번호
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.08.05.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.pgl_auctnFrmlList2_onviewchange = function(info) {
	dma_pageInfo.set("pageNo" , info.newSelectedIndex );
    dma_pageInfo.set("bfPageNo",info.oldSelectedIndex );
	scwin.auctnFrmlListMain(false,pageCnt);//조회처리
};

/**
 * 탭 이동시 해당 탭에 맞는 경매서식 목록 조회
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.08.05.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.tac_auctnFrml_ontabclick = function(tabID,idx) {

	/* 탭 인덱스 */
	var a = idx;

	if (a == "0") {/* 부동산 일 경우 */
		ibx_frmlNm1.focus();
		dma_auctnFrmlSrch.set("cortAuctnNtcEtcDtlDvsCd","0005501");
		dma_auctnFrmlSrch.set("tapFlag",a);
		/* 초기화 */
		dma_auctnFrmlSrch.set("titlSrchwd","");
		ibx_frmlNm1.setValue("");
		sbx_pageCnt1.setValue(WebSquare.cookie.getCookie('pageCnt'));
		scwin.auctnFrmlListMain(true,pageCnt);
	} else { /* 동산 일 경우 */
		ibx_frmlNm2.focus();
		dma_auctnFrmlSrch.set("cortAuctnNtcEtcDtlDvsCd","0005502");
		dma_auctnFrmlSrch.set("tapFlag",a);
		/* 초기화 */
		dma_auctnFrmlSrch.set("titlSrchwd","");
		ibx_frmlNm2.setValue("");
		sbx_pageCnt2.setValue(WebSquare.cookie.getCookie('pageCnt'));
		scwin.auctnFrmlListMain(true,pageCnt);
	}

};

/**
 * 부동산 서식명 검색
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.08.08.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.btn_auctnFrmlSrch1_onclick = function(e) {
	const srchNm = scutilo.skipSpaces(ibx_frmlNm1.getValue());
	//유효성 체크
	if (srchNm.length === 1) {
		scutilo.showMsg(scglblo.MSG.WARN,scutilo.getMsg(pgjmsg.PGJ.W_0009,"검색어"))
		return
	}
	if (pgjUtil.spcCharChk2(srchNm)) {
		scutilo.showMsg(scglblo.MSG.WARN,scutilo.getMsg(pgjmsg.PGJ.W_0004));
		return
	}
	dma_auctnFrmlSrch.set("titlSrchwd",ibx_frmlNm1.getValue());
	scwin.auctnFrmlListMain(true,pageCnt);
};

/**
 * 동산 서식명 검색
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.08.08.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.btn_auctnFrmlSrch2_onclick = function(e) {
	//유효성 체크
	const srchNm = scutilo.skipSpaces(ibx_frmlNm2.getValue());
	if (srchNm.length === 1) {
		scutilo.showMsg(scglblo.MSG.WARN,scutilo.getMsg(pgjmsg.PGJ.W_0009,"검색어"))
		return
	}
	if (pgjUtil.spcCharChk2(srchNm)) {
		scutilo.showMsg(scglblo.MSG.WARN,scutilo.getMsg(pgjmsg.PGJ.W_0004));
		return
	}
	dma_auctnFrmlSrch.set("titlSrchwd",ibx_frmlNm2.getValue());
	scwin.auctnFrmlListMain(true,pageCnt);
};

/**
 * 부동산 일때 페이지 수
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.08.08.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.sbx_pageCnt1_onchange = function(info) {

	WebSquare.cookie.setCookieAsync("test", "부동산", "None");
	var cookieFlag = info.newValue;
	if (cookieFlag == 10) {
		pgjUtil.setCookie("pageCnt","10")
	} else if (cookieFlag == 20) {
		pgjUtil.setCookie("pageCnt","20")
	} else if (cookieFlag == 30) {
		pgjUtil.setCookie("pageCnt","30")
	} else if (cookieFlag == 40) {
		pgjUtil.setCookie("pageCnt","40")
	}
	pageCnt = pgjUtil.getCookie("pageCnt");
	scwin.auctnFrmlListMain(true,cookieFlag);
};

/**
 * 동산 일때 페이지 수
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.08.08.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.sbx_pageCnt2_onchange = function(info) {
	WebSquare.cookie.setCookieAsync("test", "동산", "None");
	var cookieFlag = info.newValue;
	if (cookieFlag == 10) {
		pgjUtil.setCookie('pageCnt','10')
	} else if (cookieFlag == 20) {
		pgjUtil.setCookie('pageCnt','20')
	} else if (cookieFlag == 30) {
		pgjUtil.setCookie('pageCnt','30')
	} else if (cookieFlag == 40) {
		pgjUtil.setCookie('pageCnt','40')
	}
	pageCnt = pgjUtil.getCookie('pageCnt');
	scwin.auctnFrmlListMain(true,cookieFlag);
};


/**
 * 부동산 일때 서식클릭시 상세페이지 이동
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.08.08.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.grd_auctnFrmlList1_oncellclick = function(row,col,colId) {

	let dvsCd = dlt_auctnFrmlLst.getCellData(row, "cortAuctnNtcEtcDvsCd")
	let frmlSer = dlt_auctnFrmlLst.getCellData(row, "cortAuctnNtcMtrSeq")
	let fileSer= ""

	if (col == 2) {
		//한글파일 다운로
		fileSer = dlt_auctnFrmlLst.getCellData(row, "hwpCortAuctnAtflSeq")
		if (scutilo.isEmpty(dvsCd) || scutilo.isEmpty(dvsCd) || scutilo.isEmpty(fileSer)) {
			scutilo.showMsg(scglblo.MSG.WARN,"서식파일이 존재하지 않습니다.\n관리자에게 문의하십시오.")
			return;
		}
	} else if (col == 3) {
		//엑셀파일 다운로드
		fileSer = dlt_auctnFrmlLst.getCellData(row, "docCortAuctnAtflSeq")
		if (scutilo.isEmpty(dvsCd) || scutilo.isEmpty(dvsCd) || scutilo.isEmpty(fileSer) ) {
			scutilo.showMsg(scglblo.MSG.WARN,"서식파일이 존재하지 않습니다.\n관리자에게 문의하십시오.")
			return;
		}
	}

	if (col === 2 || col === 3) {
		const params = { "dma_downInfo": {
			cortAuctnNtcEtcDvsCd : dvsCd,
			cortAuctnNtcMtrSeq : frmlSer,
			cortAuctnAtflSeq : fileSer,
		} }

		const xhr = new XMLHttpRequest();
		xhr.open('POST', "/pgj/pgjComm/000Blob.on", true);
		xhr.setRequestHeader('Content-Type', 'application/json');
		com.setHeader(xhr); // SCHeader setting
		xhr.responseType = 'blob';
		xhr.onreadystatechange = function() {
			if (this.readyState === XMLHttpRequest.DONE) {
				if (this.status === 200) {
					let filename = "";
					let contentDisposition = this.getResponseHeader('Content-Disposition');
					if (contentDisposition && contentDisposition.indexOf('attachment') !== -1) {
						const filenameRegex = /filename[^;=\n]*=((['"]).*?\2|[^;\n]*)/;
						let matches = filenameRegex.exec(contentDisposition);
						if (matches != null && matches[1]) {
							filename = matches[1].replace(/['"]/g, '');
						}
					}
					const blob = new Blob([this.response], { type: 'application/octet-stream' });
					const downloadLink = document.createElement('a');
					downloadLink.href = URL.createObjectURL(blob);
					downloadLink.download = decodeURIComponent(filename) || 'unknown'; // 한글명 대응
					downloadLink.click();
				} else {
					scutilo.showMsg(scglblo.MSG.ERROR, '파일 다운로드에'); //<%s> 실패하였습니다.
				}
			}
		};
		xhr.send(JSON.stringify(params));
	}
};

/**
 * 동산 일때 서식클릭시 상세페이지 이동
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.08.08.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.grd_auctnFrmlList2_oncellclick = function(row,col,colId) {
	if (col == 2) {
		//한글파일 다운로드
		dvsCd  = dlt_auctnFrmlLst.getCellData(row, "cortAuctnNtcEtcDvsCd")
		frmlSer = dlt_auctnFrmlLst.getCellData(row, "cortAuctnNtcMtrSeq")
		fileSer = dlt_auctnFrmlLst.getCellData(row, "hwpCortAuctnAtflSeq")
	} else if (col == 3) {
		//엑셀파일 다운로드
		dvsCd  = dlt_auctnFrmlLst.getCellData(row, "cortAuctnNtcEtcDvsCd")
		frmlSer = dlt_auctnFrmlLst.getCellData(row, "cortAuctnNtcMtrSeq")
		fileSer = dlt_auctnFrmlLst.getCellData(row, "docCortAuctnAtflSeq")
	}

	if (col === 2 || col === 3) {
		const params = { "dma_downInfo": {
			cortAuctnNtcEtcDvsCd : dvsCd,
			cortAuctnNtcMtrSeq : frmlSer,
			cortAuctnAtflSeq : fileSer,
		} }

		const xhr = new XMLHttpRequest();
		xhr.open('POST', "/pgj/pgjComm/000Blob.on", true);
		xhr.setRequestHeader('Content-Type', 'application/json');
		com.setHeader(xhr); // SCHeader setting
		xhr.responseType = 'blob';
		xhr.onreadystatechange = function() {
			if (this.readyState === XMLHttpRequest.DONE) {
				if (this.status === 200) {
					let filename = "";
					let contentDisposition = this.getResponseHeader('Content-Disposition');
					if (contentDisposition && contentDisposition.indexOf('attachment') !== -1) {
						const filenameRegex = /filename[^;=\n]*=((['"]).*?\2|[^;\n]*)/;
						let matches = filenameRegex.exec(contentDisposition);
						if (matches != null && matches[1]) {
							filename = matches[1].replace(/['"]/g, '');
						}
					}
					const blob = new Blob([this.response], { type: 'application/octet-stream' });
					const downloadLink = document.createElement('a');
					downloadLink.href = URL.createObjectURL(blob);
					downloadLink.download = decodeURIComponent(filename) || 'unknown'; // 한글명 대응
					downloadLink.click();
				} else {
					scutilo.showMsg(scglblo.MSG.ERROR, '파일 다운로드에'); //<%s> 실패하였습니다.
				}
			}
		};
		xhr.send(JSON.stringify(params));
	}
};

/**
 * 부동산 일때 엔터키를 누를시 검색 이벤트 발동
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.11.30.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.ibx_frmlNm1_onkeydown = function(e) {
	if (e.code == "Enter") {
		scwin.btn_auctnFrmlSrch1_onclick();
	}
};

/**
 * 동산 일때 엔터키를 누를시 검색 이벤트 발동
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.11.30.   나해준       [NELS]최초 생성
